+import { db } from '@/db';
+import { inventoryService } from '@/services/inventoryService';
+
+export async function processExpireOrder(job: { data: { orderId: string } }) {
+  const order = await db.orders.findById(job.data.orderId);
+  
+  if (!order || order.status !== 'pending') {
+    return; // Already processed or paid
+  }
+  
+  // Release reserved inventory
+  for (const item of order.items) {
+    await inventoryService.release(item.productId, item.quantity);
+  }
+  
+  await order.update({ status: 'expired' });
+}
