+interface ImageVariant {
+  suffix: string;
+  width: number;
+  quality?: number;
+}
+
+const variants: ImageVariant[] = [
+  { suffix: '-thumb', width: 150, quality: 80 },
+  { suffix: '-medium', width: 600, quality: 85 },
+  { suffix: '-large', width: 1200, quality: 90 },
+];
+
+export async function uploadImage(buffer: Buffer, key: string) {
+  const baseKey = key.replace(/\.[^.]+$/, '');
+  const uploads = [];
+
+  for (const variant of variants) {
+    const resized = await sharp(buffer)
+      .resize(variant.width, null, { withoutEnlargement: true })
+      .jpeg({ quality: variant.quality || 85 })
+      .toBuffer();
+
+    uploads.push(s3.putObject({
+      Bucket: process.env.S3_BUCKET!,
+      Key: `${baseKey}${variant.suffix}.jpg`,
+      Body: resized,
+      ContentType: 'image/jpeg',
+    }).promise());
+  }
+
+  await Promise.all(uploads);
+
+  return variants.map(v => `${baseKey}${v.suffix}.jpg`);
 }
